const SITE_NAME = "DnD Miniatures STL";
const CONTACT = "seba.fyd@gmail.com";
const DEFAULT_FROM = SITE_NAME + ' <downloads@dndminiaturestl.com>';

async function paypalToken(base, id, secret) {
  const r = await fetch(base + '/v1/oauth2/token', {
    method: 'POST',
    headers: {
      Authorization: 'Basic ' + Buffer.from(id + ':' + secret).toString('base64'),
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: 'grant_type=client_credentials',
  });
  if (!r.ok) return null;
  const j = await r.json();
  return j.access_token || null;
}

module.exports = async function handler(req, res) {
  res.setHeader('Cache-Control', 'no-store');
  if (req.method !== 'POST') { res.status(405).json({ error: 'method_not_allowed' }); return; }
  try {
    const body = (req.body && typeof req.body === 'object') ? req.body : JSON.parse(req.body || '{}');
    const orderID = body.orderID;
    if (!orderID || typeof orderID !== 'string' || orderID.length > 64) { res.status(400).json({ error: 'bad_order_id' }); return; }

    const id = process.env.PAYPAL_CLIENT_ID;
    const secret = process.env.PAYPAL_SECRET;
    if (!id || !secret) { res.status(500).json({ error: 'not_configured' }); return; }

    const bases = process.env.PAYPAL_API_BASE
      ? [process.env.PAYPAL_API_BASE]
      : ['https://api-m.paypal.com', 'https://api-m.sandbox.paypal.com'];
    let order = null;
    for (const base of bases) {
      const token = await paypalToken(base, id, secret);
      if (!token) continue;
      const r = await fetch(base + '/v2/checkout/orders/' + encodeURIComponent(orderID), {
        headers: { Authorization: 'Bearer ' + token },
      });
      if (r.ok) { order = await r.json(); break; }
    }
    if (!order) { res.status(404).json({ error: 'order_not_found' }); return; }
    if (order.status !== 'COMPLETED') { res.status(402).json({ error: 'not_completed' }); return; }

    const unit = (order.purchase_units || [])[0] || {};
    const slug = unit.custom_id;
    const product = slug && CATALOG[slug];
    if (!product) { res.status(404).json({ error: 'unknown_product' }); return; }

    const cap = (((unit.payments || {}).captures) || [])[0] || {};
    const paid = parseFloat(((cap.amount || {}).value) || ((unit.amount || {}).value) || '0');
    if (!(paid + 0.001 >= product.price)) { res.status(402).json({ error: 'amount_mismatch' }); return; }

    const buyerEmail = (order.payer || {}).email_address || null;
    let emailSent = false;
    const key = process.env.RESEND_API_KEY;
    if (key && buyerEmail) {
      const linksHtml = product.links.map(function (l) {
        return '<p style="margin:10px 0"><a href="' + l.url + '" style="color:#1a7f4e;font-weight:bold">&#11015; ' + l.name + ' (.STL)</a></p>';
      }).join('');
      const html = '<div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;color:#222">'
        + '<h2 style="color:#1a1f2e">' + SITE_NAME + '</h2>'
        + '<p>Thank you for your purchase! Here ' + (product.links.length > 1 ? 'are your download links' : 'is your download link') + ' for <b>' + product.title + '</b>:</p>'
        + linksHtml
        + '<p style="font-size:13px;color:#666">License: personal use + selling physical prints is OK. Redistributing the digital files is not.</p>'
        + '<p style="font-size:13px;color:#666">Questions or print help: just reply to this email.</p>'
        + '</div>';
      try {
        const mr = await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            from: process.env.RESEND_FROM || DEFAULT_FROM,
            to: [buyerEmail],
            reply_to: CONTACT,
            subject: 'Your ' + product.title.split(' STL')[0] + ' STL — download links',
            html: html,
          }),
        });
        emailSent = mr.ok;
      } catch (e) { emailSent = false; }
    }

    res.status(200).json({ ok: true, links: product.links, emailSent: emailSent, buyerEmail: buyerEmail });
  } catch (e) {
    res.status(500).json({ error: 'delivery_failed' });
  }
};
